// Velora Heat — Three.js r186, bundled locally as ./three.bundle.min.js.
// This file keeps the import path '../vendor/three.min.js' working for the
// game modules: it re-exports the whole three.js module namespace and also
// exposes it as globalThis.THREE for the modules that read the global.
import * as THREE from './three.bundle.min.js';

globalThis.THREE = THREE;

export * from './three.bundle.min.js';
